const esc = v => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db, getState, refresh, user, listenerAttached=false, active='overview', period=30, sessions=[], projects=[], exercises=[], logs=[], goals=[], habits=[], habitLogs=[], englishAttempts=[], settings={}, timer=null, timerStart=0, elapsed=0, timerArea='english', quizQuestion=null, quizAnswered=false, quizResult=null;
const areas=[['overview','⌂','Visão geral'],['stats','▥','Estatísticas'],['english','文','Inglês'],['coding','⌘','Programação'],['exercise','✦','Exercícios'],['routine','⌁','Rotina'],['calendar','▦','Calendário'],['goals','◎','Metas'],['achievements','✦','Conquistas'],['profile','⚙','Perfil e configurações']];
const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>localDate(new Date());
const startDate=(days)=>{const d=new Date();d.setDate(d.getDate()-days+1);d.setHours(0,0,0,0);return localDate(d)};
const mins=arr=>arr.reduce((n,x)=>n+(Number(x.duration_minutes)||0),0);
const fmtMin=n=>`${Math.floor(n/60)} h ${n%60} min`;
function mount(){let old=$('#lu-progress-hub');if(old)old.remove();const host=document.createElement('section');host.id='lu-progress-hub';host.className='lu-hub';host.innerHTML=`<div class="lu-nav" role="tablist" aria-label="Áreas do LEVEL UP">${areas.map(([id,ico,name])=>`<button class="lu-nav-btn ${id===active?'active':''}" data-area="${id}" role="tab" aria-selected="${id===active}"><span>${ico}</span>${name}</button>`).join('')}</div><div id="lu-hub-content" class="lu-hub-content" aria-live="polite"></div>`;const dashboard=$('#dashboard');dashboard.append(host);host.addEventListener('click',onClick);host.addEventListener('submit',onSubmit);host.addEventListener('change',onChange);render();}
function onClick(e){const nav=e.target.closest('.lu-nav-btn[data-area]');if(nav){active=nav.dataset.area;render();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='timer-start'){startTimer(b.dataset.area||active);return}if(a==='timer-pause'){pauseTimer();return}if(a==='timer-finish'){finishTimer();return}if(a==='timer-reset'){if(timer)clearInterval(timer);timer=null;elapsed=0;renderTimerActions();return}if(a==='delete-project')deleteProject(b.dataset.id);if(a==='archive-project')archiveProject(b.dataset.id);if(a==='edit-project')editProject(b.dataset.id);if(a==='delete-exercise')deleteExercise(b.dataset.id);if(a==='edit-exercise')editExercise(b.dataset.id);if(a==='log-habit')logHabit(b.dataset.id);if(a==='delete-goal')deleteGoal(b.dataset.id);if(a==='export')exportData();if(a==='tutorial')notify('Guia rápido','Registre sessões reais, defina metas e confira sua evolução em Estatísticas.','info');if(a==='save-settings')saveSettings();if(a==='profile-avatar'){settings.avatar=b.dataset.avatar;saveSettings()}if(a==='new-session'){active=b.dataset.area||'english';render();$('[data-form="session"]')?.scrollIntoView({behavior:'smooth',block:'center'})}if(a==='mark-goal')completeGoal(b.dataset.id);if(a==='english-next'){quizQuestion=null;quizAnswered=false;quizResult=null;render()}if(a==='english-restart'){quizQuestion=null;quizAnswered=false;render()}}
async function onSubmit(e){const form=e.target;if(!form.matches('[data-form]'))return;e.preventDefault();const type=form.dataset.form;try{if(type==='english-quiz'){if(!quizQuestion||quizAnswered)throw Error('Inicie uma nova pergunta antes de responder.');const answer=form.querySelector('input[name=answer]:checked')?.value;if(answer===undefined)throw Error('Escolha uma resposta.');const correct=answer===String(quizQuestion.correct);quizResult={correct};const {error}=await db.from('lu_english_attempts').insert({user_id:user.id,question_id:quizQuestion.id,question_text:quizQuestion.question,answer_text:quizQuestion.options[Number(answer)],correct,answered_on:today()});if(error)throw error;quizAnswered=true;notify(correct?'Resposta correta!':'Continue praticando',correct?quizQuestion.explanation:`Resposta correta: ${quizQuestion.options[quizQuestion.correct]}. ${quizQuestion.explanation}`,correct?'success':'info');await loadData();render();return}if(type==='session'){const area=form.area.value;const duration=Number(form.duration_minutes.value);if(!Number.isFinite(duration)||duration<1||duration>1440)throw Error('A duração deve ser entre 1 e 1440 minutos.');const row={user_id:user.id,area,duration_minutes:duration,studied_on:form.studied_on.value||today(),content:form.content.value.trim(),category:form.category.value||area,vocabulary_count:Number(form.vocabulary_count?.value||0),lessons_count:Number(form.lessons_count?.value||0),project_id:form.project_id?.value||null};const {error}=await db.from('lu_activity_sessions').insert(row);if(error)throw error;notify('Sessão registrada',`${duration} minutos foram salvos no histórico.`,'success');form.reset();await loadData();render();return}if(type==='project'){const row={user_id:user.id,name:form.name.value.trim(),description:form.description.value.trim(),technologies:form.technologies.value.split(',').map(x=>x.trim()).filter(Boolean),status:form.status.value,progress_manual:Number(form.progress_manual.value||0)};if(!row.name)throw Error('Informe o nome do projeto.');const {error}=await db.from('lu_projects').insert(row);if(error)throw error;notify('Projeto criado','O projeto foi salvo.','success');form.reset();await loadData();render();return}if(type==='exercise'){const row={user_id:user.id,name:form.name.value.trim(),category:form.category.value,description:form.description.value.trim(),weekly_target:Number(form.weekly_target.value||3),unit:form.unit.value};if(!row.name)throw Error('Informe o nome da atividade.');const {error}=await db.from('lu_exercises').insert(row);if(error)throw error;notify('Atividade criada','Seu exercício foi salvo.','success');form.reset();await loadData();render();return}if(type==='exercise-log'){const row={user_id:user.id,exercise_id:form.exercise_id.value,performed_on:form.performed_on.value||today(),duration_minutes:Number(form.duration_minutes.value||0),sets:Number(form.sets.value||0),repetitions:Number(form.repetitions.value||0),notes:form.notes.value.trim()};const {error}=await db.from('lu_exercise_logs').insert(row);if(error)throw error;notify('Registro salvo','Atividade adicionada ao calendário.','success');form.reset();await loadData();render();return}if(type==='goal'){const row={user_id:user.id,title:form.title.value.trim(),area:form.area.value,target_value:Number(form.target_value.value||1),current_value:0,unit:form.unit.value,due_date:form.due_date.value||null};if(!row.title)throw Error('Informe o nome da meta.');const {error}=await db.from('lu_goals').insert(row);if(error)throw error;notify('Meta criada','Sua meta está salva e pronta para acompanhar.','success');form.reset();await loadData();render();return}if(type==='habit'){const row={user_id:user.id,name:form.name.value.trim(),target_per_week:Number(form.target_per_week.value||3),frequency_days:Array.from(form.querySelectorAll('[name=frequency_days]:checked')).map(x=>Number(x.value)),active:true};if(!row.name)throw Error('Informe o nome do hábito.');if(!row.frequency_days.length)throw Error('Selecione pelo menos um dia da semana.');const {error}=await db.from('lu_habits').insert(row);if(error)throw error;notify('Hábito criado','Sua rotina foi salva.','success');form.reset();await loadData();render();return}if(type==='settings'){settings={...settings,english_daily:Number(form.english_daily.value||20),english_weekly:Number(form.english_weekly.value||120),coding_daily:Number(form.coding_daily.value||30),coding_weekly:Number(form.coding_weekly.value||180),exercise_weekly:Number(form.exercise_weekly.value||3),default_session:Number(form.default_session.value||25),reduce_motion:form.reduce_motion.checked,show_animations:form.show_animations.checked,theme:form.theme.value};await persistSettings();notify('Configurações salvas','Suas preferências foram sincronizadas.','success');render();return}}catch(err){notify('Não foi possível salvar',errorMessage(err,'Confira os campos e tente novamente.'),'error')}}
function onChange(e){if(e.target.matches('[data-period]')){period=Number(e.target.value);render()}if(e.target.matches('[data-calendar-date]')){settings.calendar_date=e.target.value;render()}if(e.target.matches('[data-goal-progress]'))updateGoalProgress(e.target.dataset.goalProgress,Number(e.target.value));}
async function initProgressHub(client,stateGetter,refreshFn){db=client;getState=stateGetter;refresh=refreshFn;const state=getState();if(!state.user)return;if(user?.id===state.user.id&&$('#lu-progress-hub')){await loadData();render();return}user=state.user;await loadData();mount();if(!listenerAttached){listenerAttached=true;window.addEventListener('lu-player-data-updated',()=>{if($('#lu-progress-hub'))render()});window.addEventListener('lu-user-changed',e=>{if(!e.detail?.user){user=null;if(timer)clearInterval(timer);timer=null;elapsed=0;const h=$('#lu-progress-hub');if(h)h.remove()}else if(e.detail.user.id!==user?.id){user=e.detail.user;loadData().then(mount).catch(err=>notify('Áreas adicionais indisponíveis',errorMessage(err,'Execute a migração SQL 03 para ativar o Progress Hub.'),'error'))}})}}
async function loadData(){if(!user)return;const [s,p,x,l,g,h,hl,ea]=await Promise.all([db.from('lu_activity_sessions').select('*').eq('user_id',user.id).order('studied_on',{ascending:false}),db.from('lu_projects').select('*').eq('user_id',user.id).order('created_at',{ascending:false}),db.from('lu_exercises').select('*').eq('user_id',user.id).order('created_at',{ascending:false}),db.from('lu_exercise_logs').select('*').eq('user_id',user.id).order('performed_on',{ascending:false}),db.from('lu_goals').select('*').eq('user_id',user.id).order('created_at',{ascending:false}),db.from('lu_habits').select('*').eq('user_id',user.id).order('created_at',{ascending:false}),db.from('lu_habit_logs').select('*').eq('user_id',user.id).order('completed_on',{ascending:false}),db.from('lu_english_attempts').select('*').eq('user_id',user.id).order('created_at',{ascending:false})]);for(const r of [s,p,x,l,g,h,hl,ea])if(r.error)throw r.error;sessions=s.data||[];projects=p.data||[];exercises=x.data||[];logs=l.data||[];goals=g.data||[];habits=h.data||[];habitLogs=hl.data||[];englishAttempts=ea.data||[];const state=getState();settings={...(state.profile?.preferences||{}),...(state.profile?.preferences?.level_up||{})};}
function render(){const c=$('#lu-hub-content');if(!c)return;document.documentElement.dataset.theme=settings.theme==='light'?'light':'dark';document.body.classList.toggle('reduce-motion',!!settings.reduce_motion);document.body.classList.toggle('no-animations',settings.show_animations===false);document.querySelectorAll('.lu-nav-btn').forEach(b=>{b.classList.toggle('active',b.dataset.area===active);b.setAttribute('aria-selected',String(b.dataset.area===active))});const state=getState();const tasks=state.tasks||[];const allSessions=sessions;const range=period===0?allSessions:allSessions.filter(s=>s.studied_on>=startDate(period).slice(0,10));const done=tasks.filter(t=>t.completed_at);const now=allSessions.filter(s=>s.studied_on===today());const weekSessions=allSessions.filter(s=>s.studied_on>=startDate(7).slice(0,10));const priorSessions=allSessions.filter(s=>s.studied_on>=startDate(14).slice(0,10)&&s.studied_on<startDate(7).slice(0,10));const totalXp=Number(state.profile?.total_xp||0);const lv=levelInfo(totalXp);const common=`<div class="lu-view-heading"><div><div class="eyebrow">PLAYER DEVELOPMENT SYSTEM</div><h2>${({overview:'SUA EVOLUÇÃO',stats:'ESTATÍSTICAS',english:'CENTRO DE INGLÊS',coding:'LABORATÓRIO DE PROGRAMAÇÃO',exercise:'CENTRO DE EXERCÍCIOS',calendar:'CALENDÁRIO DE ATIVIDADES',goals:'METAS DE LONGO PRAZO',profile:'PERFIL & CONFIGURAÇÕES'})[active]}</h2><p>Dados sincronizados da sua conta. Sem estatísticas inventadas.</p></div>${active==='stats'?`<select data-period aria-label="Período"><option value="7" ${period===7?'selected':''}>7 dias</option><option value="30" ${period===30?'selected':''}>30 dias</option><option value="90" ${period===90?'selected':''}>90 dias</option><option value="0" ${period===0?'selected':''}>Todo o histórico</option></select>`:''}</div>`;let body='';if(active==='overview')body=overview(state,tasks,done,weekSessions,priorSessions,totalXp,lv);if(active==='stats')body=stats(state,tasks,range,totalXp);if(active==='english')body=studyArea('english',allSessions,projects);if(active==='coding')body=codingArea(allSessions);if(active==='exercise')body=exerciseArea();if(active==='routine')body=routineArea();if(active==='calendar')body=calendarArea(tasks);if(active==='goals')body=goalsArea();if(active==='achievements')body=achievementsArea(state,tasks);if(active==='profile')body=profileArea(state);c.innerHTML=common+body;drawCharts(c)}
function levelInfo(xp){let level=1,remaining=Math.max(0,xp);while(remaining>=level*100){remaining-=level*100;level++}return{level,current:remaining,needed:level*100,percent:remaining/(level*100)*100}}
function overview(state,tasks,done,week,prior,xp,lv){const task7=done.filter(t=>t.completed_at>=startDate(7)).length;const taskPrior=done.filter(t=>t.completed_at>=startDate(14)&&t.completed_at<startDate(7)).length;const taskDelta=taskPrior?Math.round((task7-taskPrior)/taskPrior*100):null;const studyWeek=mins(week),studyPrior=mins(prior);const delta=studyPrior?Math.round((studyWeek-studyPrior)/studyPrior*100):null;const todayM=mins(sessions.filter(s=>s.studied_on===today()));const activeSet=new Set([...sessions.map(s=>s.studied_on),...done.map(t=>t.completed_at?.slice(0,10)).filter(Boolean)]);let streak=0;let cursor=new Date();if(!activeSet.has(localDate(cursor))){cursor.setDate(cursor.getDate()-1)}while(activeSet.has(localDate(cursor))&&streak<3650){streak++;cursor.setDate(cursor.getDate()-1)}const goal=Number(settings.english_daily||20);const todayTasks=tasks.filter(t=>t.due_date===today()&&!t.completed_at&&!t.missed_at).length;const activeDays=new Set(sessions.map(s=>s.studied_on).concat(done.map(t=>t.completed_at?.slice(0,10)).filter(Boolean))).size;return `<div class="lu-kpi-grid"><article class="lu-kpi"><span>XP TOTAL</span><strong>${xp}</strong><small>Nível ${lv.level} · ${lv.needed-lv.current} XP para subir</small><div class="lu-track"><i style="width:${lv.percent}%"></i></div></article><article class="lu-kpi"><span>TAREFAS CONCLUÍDAS</span><strong>${done.length}</strong><small>${task7} nos últimos 7 dias</small></article><article class="lu-kpi"><span>ESTUDO REGISTRADO</span><strong>${fmtMin(mins(sessions))}</strong><small>${fmtMin(studyWeek)} nesta semana</small></article><article class="lu-kpi"><span>DIAS COM ATIVIDADE</span><strong>${activeDays}</strong><small>Desde o primeiro registro</small></article><article class="lu-kpi"><span>SEQUÊNCIA ATUAL</span><strong>${streak} dias</strong><small>Com atividade registrada em dias consecutivos</small></article></div><div class="lu-two-col"><section class="panel lu-card"><div class="panel-heading"><div><div class="eyebrow">ÚLTIMOS 7 DIAS</div><h3>RITMO DA SEMANA</h3></div></div><div class="lu-chart" data-chart="week"></div><p class="lu-insight">${delta===null?'Ainda não há semana anterior completa para comparar o tempo de estudo.':`Tempo de estudo ${delta>=0?'aumentou':'diminuiu'} ${Math.abs(delta)}% em relação aos 7 dias anteriores.`} ${taskDelta===null?'Ainda faltam dados para comparar tarefas com a semana anterior.':`Tarefas concluídas ${taskDelta>=0?'aumentaram':'diminuíram'} ${Math.abs(taskDelta)}% em relação aos 7 dias anteriores.`}</p></section><section class="panel lu-card"><div class="panel-heading"><div><div class="eyebrow">HOJE</div><h3>MISSÕES DO DIA</h3></div></div><div class="lu-goal-line"><span>Tarefas com prazo hoje</span><b>${todayTasks}</b></div><div class="lu-goal-line"><span>Minutos de estudo</span><b>${todayM} / ${goal}</b></div><div class="lu-track"><i style="width:${Math.min(100,todayM/Math.max(1,goal)*100)}%"></i></div><div class="lu-quick-actions"><button class="btn btn-outline" data-action="new-session" data-area="english">＋ Registrar estudo</button><button class="btn btn-outline" data-action="tutorial">Ver dicas</button></div></section></div><section class="panel lu-card"><div class="panel-heading"><div><div class="eyebrow">SUA EVOLUÇÃO</div><h3>VISÃO GERAL POR ÁREA</h3></div></div><div class="lu-area-grid">${[['Inglês',mins(sessions.filter(s=>s.area==='english'))],['Programação',mins(sessions.filter(s=>s.area==='coding'))],['Outros estudos',mins(sessions.filter(s=>!['english','coding'].includes(s.area)))],['Exercícios',logs.length]].map(([n,v])=>`<div class="lu-area-stat"><span>${n}</span><strong>${typeof v==='number'&&n!=='Exercícios'?fmtMin(v):v}</strong><small>${n==='Exercícios'?'registros salvos':'tempo registrado'}</small></div>`).join('')}</div></section>`}
function stats(state,tasks,range,xp){const done=tasks.filter(t=>t.completed_at);const byDay={};for(const s of range)byDay[s.studied_on]=(byDay[s.studied_on]||0)+Number(s.duration_minutes||0);for(const t of done){const d=t.completed_at.slice(0,10);byDay[d]=(byDay[d]||0)}const days=Object.keys(byDay).sort();const last7=range.filter(s=>s.studied_on>=startDate(7).slice(0,10));const areaM={english:mins(range.filter(s=>s.area==='english')),coding:mins(range.filter(s=>s.area==='coding')),other:mins(range.filter(s=>!['english','coding'].includes(s.area)))};return `<div class="lu-kpi-grid"><article class="lu-kpi"><span>SESSÕES</span><strong>${range.length}</strong><small>No período selecionado</small></article><article class="lu-kpi"><span>TEMPO ESTUDADO</span><strong>${fmtMin(mins(range))}</strong><small>${fmtMin(mins(last7))} nos últimos 7 dias</small></article><article class="lu-kpi"><span>TAREFAS CONCLUÍDAS</span><strong>${done.length}</strong><small>Histórico total</small></article><article class="lu-kpi"><span>XP ATUAL</span><strong>${xp}</strong><small>Saldo atual do jogador</small></article></div><div class="lu-two-col"><section class="panel lu-card"><h3>XP GANHO / PERDIDO AO LONGO DO TEMPO</h3><div class="lu-chart" data-chart="xp"></div></section><section class="panel lu-card"><h3>MINUTOS DE ESTUDO POR DIA</h3><div class="lu-chart" data-chart="study"></div></section><section class="panel lu-card"><h3>TAREFAS CONCLUÍDAS POR DIA</h3><div class="lu-chart" data-chart="tasks"></div></section></div><section class="panel lu-card"><h3>CONSISTÊNCIA POR ÁREA</h3>${Object.entries(areaM).map(([a,m])=>`<div class="lu-progress-row"><span>${a==='english'?'Inglês':a==='coding'?'Programação':'Outros estudos'}</span><b>${fmtMin(m)}</b><div class="lu-track"><i style="width:${mins(range)?m/mins(range)*100:0}%"></i></div></div>`).join('')}<p class="lu-insight">Os gráficos usam somente sessões e tarefas registradas. O XP atual não é apresentado como série histórica porque o projeto anterior não guardava snapshots diários de XP.</p></section>`}
function sessionForm(area){return `<form class="lu-form" data-form="session"><input type="hidden" name="area" value="${area}"><label>Duração (minutos)<input name="duration_minutes" type="number" min="1" max="1440" value="${Number(settings.default_session||25)}" required></label><label>Data<input name="studied_on" type="date" value="${today()}" required></label><label>Categoria<input name="category" value="${area==='english'?'Inglês':'Programação'}"></label>${area==='english'?`<label>Vocabulário novo<input name="vocabulary_count" type="number" min="0" value="0"></label><label>Lições concluídas<input name="lessons_count" type="number" min="0" value="0"></label>`:`<label>Projeto relacionado<select name="project_id"><option value="">Nenhum projeto</option>${projects.filter(p=>p.status!=='archived').map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label>`}<label class="lu-wide">Conteúdo estudado<textarea name="content" rows="3" placeholder="O que você estudou ou praticou?"></textarea></label><button class="btn btn-primary" type="submit">SALVAR SESSÃO</button></form>`}
function studyArea(area,all){const arr=all.filter(s=>s.area===area);const todayM=mins(arr.filter(s=>s.studied_on===today()));const weekM=mins(arr.filter(s=>s.studied_on>=startDate(7).slice(0,10)));const daily=Number(settings[area+'_daily']||(area==='english'?20:30));const weekly=Number(settings[area+'_weekly']||(area==='english'?120:180));return `<div class="lu-kpi-grid"><article class="lu-kpi"><span>HOJE</span><strong>${todayM} min</strong><small>Meta: ${daily} min</small><div class="lu-track"><i style="width:${Math.min(100,todayM/Math.max(1,daily)*100)}%"></i></div></article><article class="lu-kpi"><span>ESTA SEMANA</span><strong>${weekM} min</strong><small>Meta: ${weekly} min</small><div class="lu-track"><i style="width:${Math.min(100,weekM/Math.max(1,weekly)*100)}%"></i></div></article><article class="lu-kpi"><span>TEMPO TOTAL</span><strong>${fmtMin(mins(arr))}</strong><small>${arr.length} sessões registradas</small></article><article class="lu-kpi"><span>${area==='english'?'VOCABULÁRIO':'PROJETOS'}</span><strong>${area==='english'?arr.reduce((n,s)=>n+Number(s.vocabulary_count||0),0):projects.filter(p=>p.status!=='archived').length}</strong><small>${area==='english'?'palavras registradas':'projetos ativos'}</small></article></div><div class="lu-two-col"><section class="panel lu-card"><div class="panel-heading"><div><div class="eyebrow">REGISTRAR APRENDIZADO</div><h3>${area==='english'?'NOVA SESSÃO DE INGLÊS':'SESSÃO DE PROGRAMAÇÃO'}</h3></div><button class="btn btn-outline" data-action="timer-start" data-area="${area}">▶ INICIAR CRONÔMETRO</button></div><div class="lu-timer" id="lu-timer">${fmtMin(elapsed)}</div><div class="lu-timer-actions"><button class="btn btn-outline" data-action="timer-pause">PAUSAR / CONTINUAR</button><button class="btn btn-primary" data-action="timer-finish">FINALIZAR E REGISTRAR</button><button class="btn btn-outline" data-action="timer-reset">ZERAR</button></div><p class="lu-insight">O cronômetro só registra a sessão quando você finalizar. Também é possível inserir uma sessão manual abaixo.</p></section><section class="panel lu-card"><h3>METAS PERSONALIZADAS</h3><p class="muted">Ajuste as metas diárias e semanais em Perfil e configurações. Nenhum progresso é criado automaticamente.</p><div class="lu-goal-line"><span>Meta diária</span><b>${daily} min</b></div><div class="lu-goal-line"><span>Meta semanal</span><b>${weekly} min</b></div></section></div><section class="panel lu-card"><div class="panel-heading"><div><div class="eyebrow">HISTÓRICO</div><h3>SESSÕES REGISTRADAS</h3></div></div>${arr.length?`<div class="lu-history">${arr.slice(0,30).map(s=>`<article><div><b>${esc(s.content||'Sessão de estudo')}</b><small>${esc(s.studied_on)} · ${esc(s.category||area)}${area==='english'?` · ${s.vocabulary_count||0} palavras · ${s.lessons_count||0} lições`:''}</small></div><strong>${s.duration_minutes} min</strong></article>`).join('')}</div>`:`<div class="lu-empty"><b>Seu histórico começa com a primeira sessão.</b><p>Registre o tempo estudado para acompanhar sua evolução real.</p></div>`}</section><section class="panel lu-card"><h3>REGISTRAR SESSÃO MANUAL</h3>${sessionForm(area)}</section>${area==='english'?englishQuizPanel():''}`}

const englishQuestionBank=[
{id:'a1-greet',level:'Iniciante',question:'Como se diz “Bom dia” em inglês?',options:['Good morning','Good night','Goodbye','Thank you'],correct:0,explanation:'“Good morning” é usado para cumprimentar alguém pela manhã.'},
{id:'a1-verb',level:'Iniciante',question:'Complete: She ___ a student.',options:['are','is','am','be'],correct:1,explanation:'Com “she”, usamos “is” no presente do verbo to be.'},
{id:'a1-water',level:'Iniciante',question:'O que significa “water”?',options:['Comida','Janela','Água','Rua'],correct:2,explanation:'“Water” significa “água”.'},
{id:'a1-plural',level:'Iniciante',question:'Qual é o plural de “book”?',options:['bookes','books','bookies','book'],correct:1,explanation:'Na maioria dos substantivos regulares, acrescentamos -s: book → books.'},
{id:'a1-thanks',level:'Iniciante',question:'Escolha a tradução de “Thank you”.',options:['Por favor','Desculpe','Até logo','Obrigado(a)'],correct:3,explanation:'“Thank you” é uma forma comum de agradecer.'},
{id:'a1-present',level:'Iniciante',question:'Complete: I ___ from Brazil.',options:['is','are','am','be'],correct:2,explanation:'Com “I”, usamos “am”: I am from Brazil.'},
{id:'a1-cat',level:'Iniciante',question:'“The cat is small” significa:',options:['O gato é pequeno','O cão é rápido','O gato está longe','O gato é grande'],correct:0,explanation:'“Cat” é gato e “small” significa pequeno.'},
{id:'a1-question',level:'Iniciante',question:'Qual pergunta significa “Como você está?”',options:['How old are you?','Where are you?','How are you?','Who are you?'],correct:2,explanation:'“How are you?” pergunta como a pessoa está.'}
];
function pickEnglishQuestion(){const recent=new Set(englishAttempts.slice(0,4).map(a=>a.question_id));const available=englishQuestionBank.filter(q=>!recent.has(q.id));const pool=available.length?available:englishQuestionBank;quizQuestion=pool[Math.floor(Math.random()*pool.length)];quizAnswered=false;quizResult=null}
function englishQuizPanel(){const total=englishAttempts.length,correct=englishAttempts.filter(a=>a.correct).length,rate=total?Math.round(correct/total*100):0;if(!quizQuestion&&!quizAnswered)pickEnglishQuestion();const q=quizQuestion;return `<section class="panel lu-card"><div class="panel-heading"><div><div class="eyebrow">PRÁTICA INTERATIVA · A1</div><h3>DESAFIO DE INGLÊS</h3></div><span class="chip">${total} respostas registradas</span></div><div class="lu-kpi-grid"><article class="lu-kpi"><span>ACERTOS</span><strong>${correct}</strong><small>De ${total} respostas</small></article><article class="lu-kpi"><span>TAXA DE ACERTO</span><strong>${rate}%</strong><small>${total?'Com base nas suas respostas salvas':'Responda para começar seu histórico'}</small></article></div>${q?`<form class="lu-form" data-form="english-quiz"><div class="lu-wide"><span class="chip">${q.level}</span><h3>${esc(q.question)}</h3></div>${q.options.map((o,i)=>`<label class="lu-quiz-option"><input type="radio" name="answer" value="${i}" ${quizAnswered?'disabled':''} required> ${esc(o)} ${quizAnswered&&i===q.correct?' ✓':''}</label>`).join('')}${quizAnswered?`<p class="lu-insight lu-wide">${esc(q.explanation)} ${quizResult?.correct?'Muito bem! Você identificou a resposta correta.':'Revise a explicação e tente outra pergunta.'}</p><button class="btn btn-primary" type="button" data-action="english-next">PRÓXIMA PERGUNTA</button>`:`<button class="btn btn-primary" type="submit">CONFERIR RESPOSTA</button>`}</form>`:''}<p class="lu-insight">As respostas são salvas na sua conta. Esta prática introdutória não é uma certificação oficial de nível e, por enquanto, não concede XP automático.</p></section>`}

function codingArea(){const activeProjects=projects.filter(p=>p.status!=='archived');return `<section class="panel lu-card"><div class="panel-heading"><div><div class="eyebrow">SEUS PROJETOS</div><h3>LABORATÓRIO PESSOAL</h3></div></div><form class="lu-form" data-form="project"><label>Nome do projeto<input name="name" required maxlength="100" placeholder="Ex.: RPG em C"></label><label>Status<select name="status"><option value="active">Em andamento</option><option value="paused">Pausado</option><option value="completed">Concluído</option></select></label><label class="lu-wide">Descrição<textarea name="description" rows="2"></textarea></label><label>Tecnologias (separe por vírgulas)<input name="technologies" placeholder="C, Git, PostgreSQL"></label><label>Progresso manual (%)<input type="number" name="progress_manual" min="0" max="100" value="0"></label><button class="btn btn-primary" type="submit">CRIAR PROJETO</button></form><div class="lu-project-grid">${activeProjects.length?activeProjects.map(p=>`<article class="lu-project"><div class="lu-project-top"><span class="chip">${esc(p.status)}</span><button class="icon-btn" data-action="edit-project" data-id="${p.id}" title="Editar">✎</button><button class="icon-btn" data-action="archive-project" data-id="${p.id}" title="Arquivar">↗</button><button class="icon-btn" data-action="delete-project" data-id="${p.id}" title="Excluir">×</button></div><h3>${esc(p.name)}</h3><p>${esc(p.description||'Sem descrição')}</p><div class="lu-tech">${(p.technologies||[]).map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="lu-track"><i style="width:${Math.min(100,Math.max(0,p.progress_manual||0))}%"></i></div><small>${p.progress_manual||0}% de progresso manual · ${fmtMin(mins(sessions.filter(s=>s.project_id===p.id)))}</small></article>`).join(''):`<div class="lu-empty">Ainda não há projetos. Cadastre seu primeiro projeto acima.</div>`}</div></section><section class="panel lu-card"><h3>REGISTRAR TEMPO DE PROGRAMAÇÃO</h3>${sessionForm('coding')}</section><section class="panel lu-card"><h3>TEMPO POR PROJETO</h3>${activeProjects.length?activeProjects.map(p=>`<div class="lu-progress-row"><span>${esc(p.name)}</span><b>${fmtMin(mins(sessions.filter(s=>s.project_id===p.id)))}</b><div class="lu-track"><i style="width:${mins(sessions.filter(s=>s.project_id===p.id))/Math.max(1,mins(sessions))*100}%"></i></div></div>`).join(''):'<p class="lu-insight">Registre sessões associadas a um projeto para comparar o tempo dedicado.</p>'}</section>`}
function exerciseArea(){return `<div class="lu-kpi-grid"><article class="lu-kpi"><span>ATIVIDADES CADASTRADAS</span><strong>${exercises.length}</strong><small>Personalize sua lista</small></article><article class="lu-kpi"><span>REGISTROS</span><strong>${logs.length}</strong><small>Histórico salvo</small></article><article class="lu-kpi"><span>MINUTOS REGISTRADOS</span><strong>${logs.reduce((n,l)=>n+Number(l.duration_minutes||0),0)}</strong><small>Somente dados reais</small></article><article class="lu-kpi"><span>ESTA SEMANA</span><strong>${logs.filter(l=>l.performed_on>=startDate(7).slice(0,10)).length}</strong><small>sessões registradas</small></article></div><div class="lu-two-col"><section class="panel lu-card"><h3>CADASTRAR ATIVIDADE</h3><form class="lu-form" data-form="exercise"><label>Nome<input name="name" required placeholder="Ex.: Caminhada, alongamento"></label><label>Categoria<select name="category"><option>Mobilidade</option><option>Cardio</option><option>Força</option><option>Esporte</option><option>Outro</option></select></label><label>Frequência semanal desejada<input name="weekly_target" type="number" min="1" max="14" value="3"></label><label>Unidade<select name="unit"><option value="minutes">Minutos</option><option value="reps">Repetições</option><option value="sets">Séries</option><option value="sessions">Sessões</option></select></label><label class="lu-wide">Descrição<textarea name="description" rows="2"></textarea></label><button class="btn btn-primary" type="submit">SALVAR ATIVIDADE</button></form></section><section class="panel lu-card"><h3>REGISTRAR SESSÃO</h3><form class="lu-form" data-form="exercise-log"><label>Atividade<select name="exercise_id" required>${exercises.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Data<input name="performed_on" type="date" value="${today()}" required></label><label>Duração (minutos)<input name="duration_minutes" type="number" min="0" value="0"></label><label>Séries<input name="sets" type="number" min="0" value="0"></label><label>Repetições<input name="repetitions" type="number" min="0" value="0"></label><label class="lu-wide">Observações<input name="notes"></label><button class="btn btn-primary" type="submit" ${exercises.length?'':'disabled'}>REGISTRAR SESSÃO</button></form></section></div><section class="panel lu-card"><h3>SUAS ATIVIDADES</h3>${exercises.length?`<div class="lu-history">${exercises.map(x=>`<article><div><b>${esc(x.name)}</b><small>${esc(x.category)} · meta ${x.weekly_target} vezes por semana · ${logs.filter(l=>l.exercise_id===x.id).length} registros</small></div><button class="icon-btn" data-action="edit-exercise" data-id="${x.id}" title="Editar atividade">✎</button><button class="icon-btn" data-action="delete-exercise" data-id="${x.id}" title="Excluir atividade">×</button></article>`).join('')}</div>`:'<div class="lu-empty">Cadastre atividades que façam sentido para você. Não existe uma lista obrigatória.</div>'}</section><section class="panel lu-card"><h3>HISTÓRICO RECENTE</h3>${logs.length?`<div class="lu-history">${logs.slice(0,30).map(l=>`<article><div><b>${esc(exercises.find(x=>x.id===l.exercise_id)?.name||'Atividade')}</b><small>${l.performed_on} · ${l.sets||0} séries · ${l.repetitions||0} repetições</small></div><strong>${l.duration_minutes||0} min</strong></article>`).join('')}</div>`:'<p class="lu-insight">Seus registros aparecerão aqui.</p>'}</section>`}

function routineArea(){const days=[['1','Seg'],['2','Ter'],['3','Qua'],['4','Qui'],['5','Sex'],['6','Sáb'],['0','Dom']];return `<section class="panel lu-card"><h3>CRIAR HÁBITO OU ROTINA</h3><form class="lu-form" data-form="habit"><label>Nome do hábito<input name="name" required placeholder="Ex.: Revisar anotações"></label><label>Frequência desejada por semana<input name="target_per_week" type="number" min="1" max="7" value="5"></label><div class="lu-wide"><span class="field-hint">Dias planejados</span><div class="lu-days">${days.map(([v,n])=>`<label><input type="checkbox" name="frequency_days" value="${v}" checked>${n}</label>`).join('')}</div></div><button class="btn btn-primary" type="submit">ADICIONAR À ROTINA</button></form></section><section class="panel lu-card"><div class="panel-heading"><div><div class="eyebrow">CONSISTÊNCIA REAL</div><h3>ROTINA DE HOJE</h3></div><span class="chip">${today()}</span></div>${habits.length?`<div class="lu-habit-list">${habits.filter(h=>h.active).map(h=>{const done=habitLogs.some(l=>l.habit_id===h.id&&l.completed_on===today());const week=habitLogs.filter(l=>l.habit_id===h.id&&l.completed_on>=startDate(7).slice(0,10)).length;return `<article class="lu-habit"><div><b>${esc(h.name)}</b><small>${(h.frequency_days||[]).map(d=>days.find(x=>Number(x[0])===Number(d))?.[1]).filter(Boolean).join(' · ')} · ${week}/${h.target_per_week} nesta semana</small></div><button class="btn ${done?'btn-outline':'btn-primary'}" data-action="log-habit" data-id="${h.id}" ${done?'disabled':''}>${done?'CONCLUÍDO HOJE':'MARCAR FEITO'}</button></article>`}).join('')}`:'<div class="lu-empty">Cadastre um hábito acima. O LEVEL UP só registra a conclusão quando você marcar manualmente.</div>'}</section><section class="panel lu-card"><h3>HISTÓRICO DE ROTINA</h3>${habitLogs.length?`<div class="lu-history">${habitLogs.slice(0,40).map(l=>`<article><div><b>${esc(habits.find(h=>h.id===l.habit_id)?.name||'Hábito')}</b><small>Conclusão registrada</small></div><strong>${l.completed_on}</strong></article>`).join('')}</div>`:'<p class="lu-insight">Ainda não há conclusões de rotina registradas.</p>'}</section>`}
async function logHabit(id){const h=habits.find(x=>x.id===id);if(!h)return;if(habitLogs.some(l=>l.habit_id===id&&l.completed_on===today()))return;const {error}=await db.from('lu_habit_logs').insert({user_id:user.id,habit_id:id,completed_on:today()});if(error){notify('Não foi possível registrar',error.code==='23505'?'Este hábito já foi concluído hoje.':errorMessage(error),'error');return}notify('Rotina atualizada',`“${h.name}” foi registrada como concluída hoje.`,'success');await loadData();render()}
async function editExercise(id){const x=exercises.find(e=>e.id===id);if(!x)return;const name=prompt('Nome da atividade:',x.name);if(name===null)return;if(!name.trim()){notify('Nome inválido','Informe um nome para a atividade.','error');return}const description=prompt('Descrição:',x.description||'');if(description===null)return;const target=Number(prompt('Meta semanal (1 a 14):',String(x.weekly_target||3)));if(!Number.isInteger(target)||target<1||target>14){notify('Meta inválida','Escolha um número de 1 a 14.','error');return}const {error}=await db.from('lu_exercises').update({name:name.trim(),description:description.trim(),weekly_target:target}).eq('id',id).eq('user_id',user.id);if(error){notify('Falha ao editar atividade',errorMessage(error),'error');return}notify('Atividade atualizada','As alterações foram salvas.','success');await loadData();render()}
function calendarArea(tasks){const date=settings.calendar_date||today();const ts=tasks.filter(t=>(t.due_date||t.completed_at?.slice(0,10))===date);const ss=sessions.filter(s=>s.studied_on===date);const ls=logs.filter(l=>l.performed_on===date);return `<section class="panel lu-card"><div class="panel-heading"><div><div class="eyebrow">HISTÓRICO CRONOLÓGICO</div><h3>CONSULTE UM DIA</h3></div><input type="date" data-calendar-date value="${date}"></div><div class="lu-history">${[...ts.map(t=>({time:t.completed_at||t.due_at||t.created_at,title:t.title,detail:t.completed_at?'Tarefa concluída':t.missed_at?'Prazo perdido':'Tarefa agendada'})),...ss.map(s=>({time:s.studied_on,title:s.content||`Sessão de ${s.area}`,detail:`${s.duration_minutes} minutos · ${s.area}`})),...ls.map(l=>({time:l.performed_on,title:exercises.find(x=>x.id===l.exercise_id)?.name||'Exercício',detail:`${l.duration_minutes||0} minutos · ${l.sets||0} séries`}))].length?[...ts.map(t=>({time:t.completed_at||t.due_at||t.created_at,title:t.title,detail:t.completed_at?'Tarefa concluída':t.missed_at?'Prazo perdido':'Tarefa agendada'})),...ss.map(s=>({time:s.studied_on,title:s.content||`Sessão de ${s.area}`,detail:`${s.duration_minutes} minutos · ${s.area}`})),...ls.map(l=>({time:l.performed_on,title:exercises.find(x=>x.id===l.exercise_id)?.name||'Exercício',detail:`${l.duration_minutes||0} minutos · ${l.sets||0} séries`}))].map(x=>`<article><div><b>${esc(x.title)}</b><small>${esc(x.detail)}</small></div><strong>${esc(String(x.time||'').replace('T',' ').slice(0,16))}</strong></article>`).join(''):'<div class="lu-empty">Nenhuma atividade registrada para este dia. O calendário não cria atividades fictícias.</div>'}</div></section>`}
function goalsArea(){return `<section class="panel lu-card"><h3>CRIAR UMA META</h3><form class="lu-form" data-form="goal"><label>Nome da meta<input name="title" required placeholder="Ex.: Estudar inglês 120 minutos por semana"></label><label>Área<select name="area"><option value="english">Inglês</option><option value="coding">Programação</option><option value="exercise">Exercícios</option><option value="tasks">Tarefas</option><option value="personal">Pessoal</option></select></label><label>Objetivo numérico<input name="target_value" type="number" min="1" value="120" required></label><label>Unidade<input name="unit" value="minutos" required></label><label>Prazo (opcional)<input name="due_date" type="date"></label><button class="btn btn-primary" type="submit">CRIAR META</button></form></section><section class="panel lu-card"><h3>SUAS METAS</h3>${goals.length?`<div class="lu-goal-list">${goals.map(g=>`<article class="lu-goal"><div class="lu-goal-head"><div><b>${esc(g.title)}</b><small>${esc(g.area)} · ${g.due_date?`prazo ${g.due_date}`:'sem prazo'}</small></div><button class="icon-btn" data-action="delete-goal" data-id="${g.id}" title="Excluir meta">×</button></div><div class="lu-goal-line"><span>${g.current_value||0} / ${g.target_value} ${esc(g.unit)}</span><b>${Math.min(100,Math.round(Number(g.current_value||0)/Math.max(1,Number(g.target_value))*100))}%</b></div><div class="lu-track"><i style="width:${Math.min(100,Math.round(Number(g.current_value||0)/Math.max(1,Number(g.target_value))*100))}%"></i></div><label class="lu-inline-label">Atualizar progresso<input type="number" min="0" max="${g.target_value}" value="${g.current_value||0}" data-goal-progress="${g.id}"></label><button class="btn btn-outline" data-action="mark-goal" data-id="${g.id}">MARCAR CONCLUÍDA</button></article>`).join('')}</div>`:'<div class="lu-empty">Defina uma meta pequena e específica para começar. Você poderá atualizar o progresso manualmente.</div>'}</section>`}
function profileArea(state){const prefs=state.profile?.preferences||{};return `<div class="lu-profile-hero panel"><div class="lu-profile-avatar">${esc(settings.avatar||'⚔')}</div><div><div class="eyebrow">IDENTIDADE DO JOGADOR</div><h3>${esc(state.profile?.player_name||user.email?.split('@')[0]||'Jogador')}</h3><p>${esc(user.email||'')} · desde ${esc(String(state.profile?.created_at||'').slice(0,10)||'data indisponível')}</p><div class="player-title">NÍVEL ${levelInfo(Number(state.profile?.total_xp||0)).level} · ${Number(state.profile?.total_xp||0)} XP</div></div></div><section class="panel lu-card"><h3>PERSONALIZAR AVATAR</h3><div class="lu-avatar-options">${['⚔','🛡','🦊','🐺','🤖','👾','🚀','🔥'].map(a=>`<button class="lu-avatar-choice ${settings.avatar===a?'selected':''}" data-action="profile-avatar" data-avatar="${a}" aria-label="Escolher avatar ${a}">${a}</button>`).join('')}</div><p class="lu-insight">O avatar é uma preferência visual privada e fica salvo no seu perfil.</p></section><section class="panel lu-card"><h3>METAS E PREFERÊNCIAS DE PRODUTIVIDADE</h3><form class="lu-form" data-form="settings"><label>Meta diária de inglês (minutos)<input name="english_daily" type="number" min="1" max="600" value="${Number(settings.english_daily||20)}"></label><label>Meta semanal de inglês (minutos)<input name="english_weekly" type="number" min="1" max="3000" value="${Number(settings.english_weekly||120)}"></label><label>Meta diária de programação (minutos)<input name="coding_daily" type="number" min="1" max="600" value="${Number(settings.coding_daily||30)}"></label><label>Meta semanal de programação (minutos)<input name="coding_weekly" type="number" min="1" max="3000" value="${Number(settings.coding_weekly||180)}"></label><label>Meta semanal de exercícios (sessões)<input name="exercise_weekly" type="number" min="1" max="14" value="${Number(settings.exercise_weekly||3)}"></label><label>Duração padrão da sessão (minutos)<input name="default_session" type="number" min="1" max="240" value="${Number(settings.default_session||25)}"></label><label>Tema<select name="theme"><option value="dark" ${settings.theme!=='light'?'selected':''}>Escuro gamer</option><option value="light" ${settings.theme==='light'?'selected':''}>Claro</option></select></label><label class="lu-check"><input name="show_animations" type="checkbox" ${settings.show_animations!==false?'checked':''}> Animações da interface</label><label class="lu-check"><input name="reduce_motion" type="checkbox" ${settings.reduce_motion?'checked':''}> Reduzir movimento</label><button class="btn btn-primary" type="submit">SALVAR CONFIGURAÇÕES</button></form></section><section class="panel lu-card"><h3>SEUS DADOS</h3><p class="lu-insight">Exporte uma cópia dos seus registros para guardar localmente. Isso não exclui dados do servidor.</p><button class="btn btn-outline" data-action="export">EXPORTAR MEUS DADOS (JSON)</button><button class="btn btn-outline" data-action="tutorial">REVER GUIA RÁPIDO</button><p class="field-hint">A exclusão de conta não é executada pelo navegador: por segurança, solicite-a pelo canal de suporte do projeto Supabase ou implemente uma função administrativa protegida.</p></section>`}

function achievementsArea(state,tasks){const done=tasks.filter(t=>t.completed_at).length;const activeDates=new Set([...sessions.map(s=>s.studied_on),...tasks.map(t=>t.completed_at?.slice(0,10)).filter(Boolean)]);const unlocked=[['✦','Primeiro passo','Conclua sua primeira tarefa.',done>=1],['◈','Aprendiz','Registre sua primeira sessão de estudo.',sessions.length>=1],['⌘','Criador','Cadastre seu primeiro projeto.',projects.length>=1],['⚡','Consistência','Tenha atividade registrada em 7 dias diferentes.',activeDates.size>=7],['✓','Mão na massa','Conclua 5 tarefas.',done>=5],['★','Nível 5','Alcance o nível 5.',levelInfo(Number(state.profile?.total_xp||0)).level>=5],['🏃','Movimento','Registre sua primeira sessão de exercício.',logs.length>=1],['◎','Planejador','Crie sua primeira meta.',goals.length>=1],['♜','Meta concluída','Conclua uma meta pessoal.',goals.some(g=>g.completed_at||Number(g.current_value)>=Number(g.target_value))]];return `<div class="lu-kpi-grid"><article class="lu-kpi"><span>CONQUISTAS DESBLOQUEADAS</span><strong>${unlocked.filter(a=>a[3]).length}</strong><small>De ${unlocked.length} conquistas verificáveis</small></article><article class="lu-kpi"><span>REGISTROS DE ESTUDO</span><strong>${sessions.length}</strong><small>Baseados no seu histórico</small></article><article class="lu-kpi"><span>PROJETOS</span><strong>${projects.length}</strong><small>Criados por você</small></article><article class="lu-kpi"><span>METAS CONCLUÍDAS</span><strong>${goals.filter(g=>g.completed_at||Number(g.current_value)>=Number(g.target_value)).length}</strong><small>Com base no progresso registrado</small></article></div><section class="panel lu-card"><div class="panel-heading"><div><div class="eyebrow">SUA JORNADA</div><h3>CONQUISTAS E REQUISITOS</h3></div></div><div class="lu-achievement-grid">${unlocked.map(a=>`<article class="lu-achievement ${a[3]?'is-unlocked':'is-locked'}"><span>${a[0]}</span><div><b>${a[1]}</b><small>${a[2]}</small></div><strong>${a[3]?'DESBLOQUEADA':'BLOQUEADA'}</strong></article>`).join('')}</div><p class="lu-insight">As condições são calculadas a partir dos registros reais. Esta versão não concede XP extra por conquistas, evitando recompensas duplicadas.</p></section>`}
async function editProject(id){const p=projects.find(x=>x.id===id);if(!p)return;const name=prompt('Nome do projeto:',p.name);if(name===null)return;if(!name.trim()){notify('Nome inválido','O projeto precisa de um nome.','error');return}const description=prompt('Descrição do projeto:',p.description||'');if(description===null)return;const technologies=prompt('Tecnologias separadas por vírgula:',(p.technologies||[]).join(', '));if(technologies===null)return;const {error}=await db.from('lu_projects').update({name:name.trim(),description:description.trim(),technologies:technologies.split(',').map(x=>x.trim()).filter(Boolean)}).eq('id',id).eq('user_id',user.id);if(error){notify('Falha ao editar projeto',errorMessage(error),'error');return}notify('Projeto atualizado','As alterações foram salvas.','success');await loadData();render()}
function drawCharts(root){
 const ts=getState().tasks||[];
 const week=root.querySelector('[data-chart="week"]');
 if(week){const data=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=localDate(d);data.push({key,label:d.toLocaleDateString('pt-BR',{weekday:'short'}),value:mins(sessions.filter(s=>s.studied_on===key))})}week.innerHTML=barChart(data,'min')}
 const firstDate=[...sessions.map(s=>s.studied_on),...ts.map(t=>(t.completed_at||t.missed_at||t.created_at||'').slice(0,10)).filter(Boolean)].sort()[0]||today();
 const buckets=[];
 if(period===0){let cursor=new Date(firstDate+'T12:00:00');cursor.setDate(1);const end=new Date();end.setDate(1);while(cursor<=end){const y=cursor.getFullYear(),m=cursor.getMonth(),key=`${y}-${String(m+1).padStart(2,'0')}`;buckets.push({key,label:cursor.toLocaleDateString('pt-BR',{month:'short',year:'2-digit'}),from:`${key}-01`,to:null});cursor.setMonth(cursor.getMonth()+1)}if(!buckets.length)buckets.push({key:today().slice(0,7),label:new Date().toLocaleDateString('pt-BR',{month:'short',year:'2-digit'}),from:today().slice(0,7)+'-01',to:null});for(let i=0;i<buckets.length;i++){const next=buckets[i+1];buckets[i].to=next?next.from:today()+'\uFFFF'}}
 else {for(let i=period-1;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const k=localDate(d);buckets.push({key:k,label:d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}),from:k,to:k+'\uFFFF'})}}
 const bucketVal=(bucket,fn)=>fn(bucket);
 const study=root.querySelector('[data-chart="study"]');if(study){const data=buckets.map(b=>({key:b.key,label:b.label,value:bucketVal(b,x=>mins(sessions.filter(s=>s.studied_on>=x.from&&s.studied_on<x.to)))}));study.innerHTML=barChart(data,'min')}
 const taskChart=root.querySelector('[data-chart="tasks"]');if(taskChart){const data=buckets.map(b=>({key:b.key,label:b.label,value:bucketVal(b,x=>ts.filter(t=>t.completed_at&&t.completed_at.slice(0,10)>=x.from&&t.completed_at.slice(0,10)<x.to).length)}));taskChart.innerHTML=barChart(data,'tarefas')}
 const xpChart=root.querySelector('[data-chart="xp"]');if(xpChart){let running=0;const data=buckets.map(b=>{const delta=ts.reduce((sum,t)=>sum+(t.completed_at&&t.completed_at.slice(0,10)>=b.from&&t.completed_at.slice(0,10)<b.to?Number(t.xp_awarded||50):0)-(t.missed_at&&t.missed_at.slice(0,10)>=b.from&&t.missed_at.slice(0,10)<b.to?Number(t.xp_penalty||25):0),0);running+=delta;return {key:b.key,label:b.label,value:Math.max(0,running)}});xpChart.innerHTML=barChart(data,'XP acumulado no período')}
}
async function persistSettings(){const state=getState();const preferences={...(state.profile?.preferences||{}),level_up:settings};const {data,error}=await db.from('lu_profiles').update({preferences}).eq('user_id',user.id).select().single();if(error)throw error}
async function saveSettings(){try{await persistSettings();const theme=settings.theme==='light'?'light':'dark';document.documentElement.dataset.theme=theme;document.body.classList.toggle('reduce-motion',!!settings.reduce_motion);notify('Preferências salvas','As configurações foram sincronizadas com seu perfil.','success')}catch(e){notify('Falha ao salvar configuração',errorMessage(e),'error')}}
async function updateGoalProgress(id,value){const g=goals.find(x=>x.id===id);if(!g)return;const {error}=await db.from('lu_goals').update({current_value:Math.max(0,Math.min(g.target_value,value))}).eq('id',id).eq('user_id',user.id);if(error){notify('Falha ao atualizar meta',errorMessage(error),'error');return}await loadData();render()}
async function completeGoal(id){const g=goals.find(x=>x.id===id);if(!g)return;const {error}=await db.from('lu_goals').update({current_value:g.target_value,completed_at:new Date().toISOString()}).eq('id',id).eq('user_id',user.id);if(error){notify('Falha ao concluir meta',errorMessage(error),'error');return}notify('Meta concluída','Progresso atualizado.','success');await loadData();render()}
async function deleteProject(id){if(!confirm('Excluir este projeto e desvincular suas sessões?'))return;const {error}=await db.from('lu_projects').delete().eq('id',id).eq('user_id',user.id);if(error){notify('Falha ao excluir projeto',errorMessage(error),'error');return}await loadData();render()}
async function archiveProject(id){const {error}=await db.from('lu_projects').update({status:'archived'}).eq('id',id).eq('user_id',user.id);if(error){notify('Falha ao arquivar projeto',errorMessage(error),'error');return}await loadData();render()}
async function deleteExercise(id){if(!confirm('Excluir esta atividade e os registros associados?'))return;const {error}=await db.from('lu_exercises').delete().eq('id',id).eq('user_id',user.id);if(error){notify('Falha ao excluir atividade',errorMessage(error),'error');return}await loadData();render()}
async function deleteGoal(id){if(!confirm('Excluir esta meta?'))return;const {error}=await db.from('lu_goals').delete().eq('id',id).eq('user_id',user.id);if(error){notify('Falha ao excluir meta',errorMessage(error),'error');return}await loadData();render()}
function startTimer(area){timerArea=area;if(timer){pauseTimer();return}timerStart=Date.now();timer=setInterval(()=>{elapsed+=Math.floor((Date.now()-timerStart)/1000);timerStart=Date.now();const el=$('#lu-timer');if(el)el.textContent=`${Math.floor(elapsed/3600)} h ${Math.floor(elapsed%3600/60)} min ${elapsed%60} s`},1000);notify('Cronômetro iniciado',`Sessão de ${area==='english'?'inglês':'programação'} em andamento.`,'info');renderTimerActions()}
function pauseTimer(){if(timer){clearInterval(timer);timer=null;elapsed+=Math.floor((Date.now()-timerStart)/1000);notify('Cronômetro pausado','O tempo acumulado foi preservado.','info')}else if(elapsed){timerStart=Date.now();timer=setInterval(()=>{elapsed+=Math.floor((Date.now()-timerStart)/1000);timerStart=Date.now();const el=$('#lu-timer');if(el)el.textContent=`${Math.floor(elapsed/3600)} h ${Math.floor(elapsed%3600/60)} min ${elapsed%60} s`},1000)}renderTimerActions()}
function renderTimerActions(){const el=$('#lu-timer');if(el)el.textContent=`${Math.floor(elapsed/3600)} h ${Math.floor(elapsed%3600/60)} min ${elapsed%60} s`}
async function finishTimer(){if(!timer&&!elapsed){notify('Cronômetro vazio','Inicie o cronômetro ou registre uma sessão manual.','info');return}if(timer){clearInterval(timer);timer=null;elapsed+=Math.floor((Date.now()-timerStart)/1000)}const duration=Math.max(1,Math.round(elapsed/60));if(!user)return;const {error}=await db.from('lu_activity_sessions').insert({user_id:user.id,area:timerArea,duration_minutes:duration,studied_on:today(),category:timerArea,content:'Sessão registrada pelo cronômetro'});if(error){notify('Falha ao salvar cronômetro',errorMessage(error),'error');return}elapsed=0;notify('Sessão registrada',`${duration} minutos adicionados ao histórico.`,'success');await loadData();render()}
function exportData(){const data={exported_at:new Date().toISOString(),profile:getState().profile,tasks:getState().tasks,sessions,projects,exercises,exercise_logs:logs,goals,habits,habit_logs:habitLogs};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`level-up-export-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Exportação iniciada','O arquivo JSON contém os registros carregados da sua conta.','success')}
